    if (typeof url === "string" && /google\.com/.test(url) && /oauth|gsi|o\/oauth/.test(url)) {
      var w = 520;
      var h = 640;
      var sw = window.screen.availWidth || screen.width;
      var sh = window.screen.availHeight || screen.height;
      var left = Math.max(0, Math.round((sw - w) / 2));
      var top = Math.max(0, Math.round((sh - h) / 2));
      var geo = "width=" + w + ",height=" + h + ",left=" + left + ",top=" + top + ",scrollbars=yes,resizable=yes";
      specs = specs ? specs + "," + geo : geo;
    }
    return orig.call(window, url, name, specs);
  };
  try {
    runFn();
  } finally {
    /* restore after delay — popup abre de forma síncrona */
  }
  setTimeout(function() {
    window.open = orig;
  }, 3000);
}
